    for (let j = n - 1; j >= 0; j--) {
      dp[i][j] = base[i] === side[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1])
    }
  }
  return dp
}

/**
 * Walks `base` and `side` together, matching a line whenever both sides
 * agree and otherwise advancing whichever side keeps the longest possible
 * subsequence (base on a tie), turning every unmatched stretch into a
 * change: a run of base lines (by index range) replaced by a run of the
 * side's lines.
 */
export function computeChanges(base, side) {
  const m = base.length
  const n = side.length
  const dp = buildLcsTable(base, side)
  const changes = []
  let i = 0
  let j = 0
  while (i < m || j < n) {
    if (i < m && j < n && base[i] === side[j]) {
      i++
      j++
      continue
    }
    const start = i
    const lines = []
    while ((i < m || j < n) && !(i < m && j < n && base[i] === side[j])) {
      if (j >= n || (i < m && dp[i + 1][j] >= dp[i][j + 1])) {
        i++
      } else {
        lines.push(side[j])
        j++
      }
    }
    changes.push({ start, end: i, lines })
  }
  return changes
}

