  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false
  return true
}

/**
 * Groups the changes from both sides into regions: a region starts at the
 * first remaining change's base range and keeps absorbing later changes
 * (from either side) whose base start is at or before the region's current
 * end, extending the end to cover them.
 */
function groupRegions(mineChanges, theirsChanges) {
  const combined = []
  for (const c of mineChanges) combined.push({ ...c, side: 'mine' })
  for (const c of theirsChanges) combined.push({ ...c, side: 'theirs' })
  combined.sort((a, b) => {
    if (a.start !== b.start) return a.start - b.start
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })

  const regions = []
  let idx = 0
  while (idx < combined.length) {
    const first = combined[idx++]
    let end = first.end
    const changes = [first]
    while (idx < combined.length && combined[idx].start <= end) {
      end = Math.max(end, combined[idx].end)
      changes.push(combined[idx])
      idx++
    }
    regions.push({ start: first.start, end, changes })
  }
  return regions
