  const lines = []
  let pos = region.start
  for (const c of changes) {
    for (let k = pos; k < c.start; k++) lines.push(base[k])
    for (const line of c.lines) lines.push(line)
    pos = c.end
  }
  for (let k = pos; k < region.end; k++) lines.push(base[k])
  return lines
