  const mineChanges = computeChanges(base, mine)
  const theirsChanges = computeChanges(base, theirs)
  const regions = groupRegions(mineChanges, theirsChanges)

  const timeline = []
  let pos = 0
  for (const region of regions) {
    if (region.start > pos) timeline.push({ type: 'stable', lines: base.slice(pos, region.start) })
    timeline.push(resolveRegion(base, region))
    pos = region.end
  }
  if (pos < base.length) timeline.push({ type: 'stable', lines: base.slice(pos, base.length) })
  return timeline
}
