  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false
  return true
}

/**
 * Groups the changes from both sides into regions: a region starts at the
 * first remaining change's base range and keeps absorbing later changes
 * (from either side) whose base start is at or before the region's current
 * end, extending the end to cover them.
 */
function groupRegions(mineChanges, theirsChanges) {
  const combined = []
  for (const c of mineChanges) combined.push({ ...c, side: 'mine' })
  for (const c of theirsChanges) combined.push({ ...c, side: 'theirs' })
  combined.sort((a, b) => {
    if (a.start !== b.start) return a.start - b.start
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })

  const regions = []
  let idx = 0
  while (idx < combined.length) {
    const first = combined[idx++]
    let end = first.end
    const changes = [first]
    while (idx < combined.length && combined[idx].start <= end) {
      end = Math.max(end, combined[idx].end)
      changes.push(combined[idx])
      idx++
    }
    regions.push({ start: first.start, end, changes })
  }
  return regions
}

/**
 * Reconstructs one side's lines across a region: base lines outside that
 * side's own changes, stitched together with the changed lines in between.
 */
function stitchSide(base, region, changes) {
  const lines = []
  let pos = region.start
  for (const c of changes) {
    for (let k = pos; k < c.start; k++) lines.push(base[k])
    for (const line of c.lines) lines.push(line)
    pos = c.end
  }
  for (let k = pos; k < region.end; k++) lines.push(base[k])
  return lines
}

/**
 * Resolves a region to one side, to "both" when the sides made the same
 * change, or to a conflict, per the merge rules.
 */
function resolveRegion(base, region) {
  const mineChanges = region.changes.filter(c => c.side === 'mine')
  const theirsChanges = region.changes.filter(c => c.side === 'theirs')
  const mine = stitchSide(base, region, mineChanges)
  const theirs = stitchSide(base, region, theirsChanges)
  const baseLines = base.slice(region.start, region.end)

  if (arraysEqual(mine, theirs)) return { type: 'resolved', label: 'both', lines: mine }
  if (arraysEqual(mine, baseLines)) return { type: 'resolved', label: 'theirs', lines: theirs }
  if (arraysEqual(theirs, baseLines)) return { type: 'resolved', label: 'mine', lines: mine }
  return { type: 'conflict', mine, base: baseLines, theirs }
}

/**
 * Computes the full three-way merge as an ordered timeline of stable
 * regions (kept unchanged from the base) and resolved-or-conflicting
 * regions covering the changed stretches.
 */
export function buildTimeline(mine, base, theirs) {
  const mineChanges = computeChanges(base, mine)
  const theirsChanges = computeChanges(base, theirs)
  const regions = groupRegions(mineChanges, theirsChanges)

  const timeline = []
  let pos = 0
  for (const region of regions) {
    if (region.start > pos) timeline.push({ type: 'stable', lines: base.slice(pos, region.start) })
    timeline.push(resolveRegion(base, region))
    pos = region.end
  }
  if (pos < base.length) timeline.push({ type: 'stable', lines: base.slice(pos, base.length) })
  return timeline
}
"}

{"file_path":"src/format.js","content":"/**
 * Renders a merge timeline (see src/diff3.js) into the output for each of
 * the three CLI modes.
 */

function linesToText(lines) {
  return lines.length ? `${lines.join('\n')}\n` : ''
}

/**
 * `merge` and `merge2` output: resolved lines in place, conflicts as
 * marker blocks. `merge2` omits the `|||||||` base section.
 */
export function formatMerge(timeline, { includeBase }) {
  const out = []
  let conflict = false
  for (const item of timeline) {
    if (item.type === 'conflict') {
      conflict = true
      out.push('<<<<<<< mine', ...item.mine)
      if (includeBase) out.push('||||||| base', ...item.base)
      out.push('=======', ...item.theirs, '>>>>>>> theirs')
    } else {
      out.push(...item.lines)
    }
  }
  return { text: linesToText(out), conflict }
}

/** `regions` output: one classification line per region. */
export function formatRegions(timeline) {
  const out = []
  let conflict = false
  for (const item of timeline) {
    if (item.type === 'stable') {
      out.push(`stable ${item.lines.length}`)
    } else if (item.type === 'resolved') {
      out.push(`${item.label} ${item.lines.length}`)
    } else {
      conflict = true
      out.push(`conflict mine=${item.mine.length} base=${item.base.length} theirs=${item.theirs.length}`)
    }
  }
  return { text: linesToText(out), conflict }
}
"}

{"file_path":"src/parse.js","content":"/** Thrown for malformed input; its message is written verbatim to stderr. */
export class InputError extends Error {}

/**
 * Splits raw stdin text into lines (dropping the empty tail a trailing
 * newline leaves) and then into exactly three documents separated by lines
 * that are exactly `%%%`.
 */
export function parseDocuments(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') parts.push([])
    else parts[parts.length - 1].push(line)
  }

  if (parts.length !== 3) throw new InputError('expected three parts separated by %%%')
  return parts
}
"}

