/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { readFileSync } from 'node:fs'
import { buildTimeline } from './diff3.js'
import { formatMerge, formatRegions } from './format.js'
import { InputError, parseDocuments } from './parse.js'

const MODES = new Set(['merge', 'merge2', 'regions'])

function fail(message) {
  process.stderr.write(`${message}\n`)
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || !MODES.has(mode)) {
    fail('error: usage: cli.js merge|merge2|regions')
  }

  let mine, base, theirs
  try {
    ;[mine, base, theirs] = parseDocuments(readFileSync(0, 'utf8'))
  } catch (err) {
    if (err instanceof InputError) fail(`error: ${err.message}`)
    throw err
  }

  const timeline = buildTimeline(mine, base, theirs)
  const { text, conflict } =
    mode === 'regions' ? formatRegions(timeline) : formatMerge(timeline, { includeBase: mode === 'merge' })

  process.stdout.write(text)
  process.exit(conflict ? 1 : 0)
}

main()
"}

